INSERT INTO "Game" ("id","slug","title","description","tag","categories","tech","year","emoji","bgColor","published","sortOrder","portfolioSection","projectContext","role","contribution","contributions","team","recognition","features","highlights","platforms","inDevelopment","updatedAt")
VALUES (gen_random_uuid()::text, $q$lion-simulator$q$, $q$Lion Simulator: Wild African Savanna Survival$q$, $q$A 3D wildlife survival simulator for mobile where you raise a lion from a cub to a pride leader across an African savanna. You hunt, fight rival predators, grow through life stages and take on chapter based objectives. It was the most simulation focused game our company built for the App Store.$q$, $q$Simulation$q$, ARRAY[$q$Simulation$q$, $q$Action$q$, $q$RPG$q$, $q$Mobile$q$, $q$Unity 3D$q$, $q$Wildlife$q$, $q$Open World$q$]::text[], $q$Unity, C#, URP, AppLovin MAX, GameAnalytics, Unity IAP, Feel$q$, $q$2026$q$, $q$🦁$q$, $q$#b45309$q$, true, 6, $q$GAME$q$, $q$COMPANY$q$, $q$Lead gameplay and systems programmer$q$, $q$I built the core gameplay: lion movement, lock-on combat, animal behaviour, the chapter and objective system, and the ad and analytics setup. I also handled mobile touch controls, camera smoothing and effects so the game runs smoothly on phones.$q$, ARRAY[$q$Lion movement with sprint, pounce, terrain alignment and swimming with splash effects$q$, $q$Lock-on combat with target selection, hit feedback and combo attacks$q$, $q$Animal behaviour: pack hunting, prey grazing and fleeing, rival predators and cubs in the den$q$, $q$Growth and progression from cub to king lion with stats and level-up perks$q$, $q$Chapter based mission system for hunting quotas, territory marking and story steps$q$, $q$Ad placement (rewarded revives, interstitials) tied to GameAnalytics tracking$q$, $q$Mobile controls with a floating joystick, context action buttons and touch camera$q$]::text[], ARRAY[$q$Me (programmer)$q$, $q$One environment artist$q$, $q$One game designer$q$]::text[], $q$Built for App Store release.$q$, ARRAY[$q$Open world savanna with different wildlife habitats$q$, $q$Full life cycle progression from cub to adult leader$q$, $q$Lock-on combat with pounce attacks and finishing claw strikes$q$, $q$Interactive pride den where cubs play and rest$q$, $q$Multi-chapter quest system$q$, $q$Rewarded second chance revive and level-up reward cards$q$]::text[], ARRAY[$q$State machine character controller for idle, sprint, prowl, pounce, swim and combat$q$, $q$Target scoring based on distance and angle so lock-on feels right on a touchscreen$q$, $q$Ad mediation with cooldowns, tutorial protection and placement safety checks$q$, $q$Funnel analytics tracking quest time, retries and where players quit$q$, $q$Mobile performance work: draw call budget, object pooling for effects and damage popups, lightweight URP shaders$q$]::text[], $q$Mobile (Android and iOS)$q$, false, CURRENT_TIMESTAMP)
