INSERT INTO "Game" ("id","slug","title","description","tag","categories","tech","year","emoji","bgColor","published","sortOrder","portfolioSection","projectContext","role","contribution","contributions","team","recognition","features","highlights","platforms","inDevelopment","updatedAt")
VALUES (gen_random_uuid()::text, $q$dust-run-fps-runner$q$, $q$Dust Run: Tactical On-Rails FPS Runner$q$, $q$A mix of first person shooter and endless runner in the style of Into the Dead. The player moves forward along a track, fights through enemy waves, and uses a turret setup alongside walking and running. It is a company project aimed at the App Store and is still in development.$q$, $q$Action & Shooter$q$, ARRAY[$q$FPS$q$, $q$Runner$q$, $q$Action$q$, $q$Unity 6$q$, $q$Mobile$q$, $q$Gameplay Systems$q$]::text[], $q$Unity 6, C#, URP, Unity Input System, Unity AI Navigation$q$, $q$2026$q$, $q$🏃$q$, $q$#7c2d12$q$, true, 7, $q$GAME$q$, $q$COMPANY$q$, $q$Lead gameplay programmer and technical designer$q$, $q$I built the runner movement, the spline track tools, the enemy wave system and the turret mechanic, and I keep the whole thing running smoothly on mobile.$q$, ARRAY[$q$Custom spline track tools with editor gizmos, width limits and progress tracking$q$, $q$First person runner controller with automatic running and manual walking with side movement$q$, $q$Wave director with gate triggers, enemies arriving one wave at a time, cleanup of enemies left behind and endless looping$q$, $q$RCC and turret mechanic with walking and running states$q$, $q$Pooling and allocation free code in the hot loops for steady mobile performance$q$]::text[], ARRAY[$q$Me$q$, $q$One game designer$q$, $q$One 3D artist$q$]::text[], NULL, ARRAY[$q$Constant forward movement along a track with side dodging$q$, $q$Gate triggered enemy encounters$q$, $q$Enemies removed behind the player and reused through pooling$q$, $q$Keyboard and mouse controls plus touch fire and drag controls$q$, $q$Runner mode built on top of the existing FPS combat without breaking it$q$]::text[], ARRAY[$q$Track progress is calculated at runtime without heavy physics checks$q$, $q$Enemies spawn along the track direction so they appear ahead of the player$q$, $q$Cached references and no garbage allocation in frequent loops$q$, $q$Kept in its own isolated module so the main project stays stable$q$]::text[], $q$PC and mobile$q$, true, CURRENT_TIMESTAMP)
