VALUES (gen_random_uuid()::text, $q$curioverse-ar$q$, $q$CurioVerse: AR Quiz and Chemistry Lab$q$, $q$An AR app built for a software engineering course. It works as a quiz app for AR content and includes a 3D AR chemistry lab where users can experience experiments in their own space.$q$, $q$AR/VR & Tools$q$, ARRAY[$q$Augmented Reality$q$, $q$XR$q$, $q$Education$q$, $q$Mobile$q$, $q$Unity$q$]::text[], $q$Unity, C#, AR Foundation, XR Interaction Toolkit, ARCore, ARKit, URP$q$, $q$2024$q$, $q$🥽$q$, $q$#581c87$q$, true, 9, $q$GAME$q$, $q$ACADEMIC$q$, $q$Unity and AR developer$q$, $q$I built the AR interaction experience: surface detection, placing objects, onboarding and the interface around it.$q$, ARRAY[$q$Surface scanning and object placement$q$, $q$Object selection, movement, scaling, rotation and deletion$q$, $q$Onboarding flow that teaches each interaction step by step$q$, $q$Plane visualization and an AR debug menu$q$, $q$Custom occlusion shader and fading plane effect$q$]::text[], ARRAY[$q$Software engineering course team$q$]::text[], NULL, ARRAY[$q$Tap to place 3D objects$q$, $q$Selectable object library$q$, $q$Guided onboarding$q$, $q$Quiz and chemistry lab content$q$, $q$Debug menu and editor simulation support$q$]::text[], ARRAY[$q$Spawner places objects on the detected surface and faces them toward the camera$q$, $q$Onboarding steps are sequenced with coroutines and events$q$, $q$Custom shader for AR occlusion$q$, $q$Mobile friendly URP setup$q$]::text[], $q$Mobile AR$q$, false, CURRENT_TIMESTAMP)
