INSERT INTO "Game" ("id","slug","title","description","tag","categories","tech","year","emoji","bgColor","published","sortOrder","portfolioSection","projectContext","role","contribution","contributions","team","recognition","features","highlights","platforms","inDevelopment","updatedAt")
VALUES (gen_random_uuid()::text, $q$echoes-of-you$q$, $q$Echoes of You: Adaptive Psychological Survival Horror$q$, $q$A first person horror game where the enemies learn how you hide. You play a dying man moving through three memory spaces: a forest maze, a suburban street and a family home. Each monster is the same buried trauma in a different disguise, and the AI remembers your favorite hiding spots and ambushes them.$q$, $q$Horror & Adventure$q$, ARRAY[$q$Horror$q$, $q$Reinforcement Learning$q$, $q$Adaptive AI$q$, $q$Procedural Generation$q$, $q$Unity 6$q$]::text[], $q$Unity 6, C#, URP, Q-Learning, Unity AI Navigation, Cinemachine, Input System, Blender$q$, $q$2026$q$, $q$👁️$q$, $q$#1f1d2e$q$, true, 1, $q$GAME$q$, $q$ACADEMIC$q$, $q$Lead Unity developer and author of the original proposal$q$, $q$I built the core gameplay, player controller, level progression and the procedural maze, then tied together the learning AI, the habit tracker and the enemy controllers across all three levels.$q$, ARRAY[$q$Procedural forest maze carved into terrain with a recursive backtracking algorithm and runtime NavMesh baking$q$, $q$First person movement with stamina sprint, crouch, hiding and item inspection$q$, $q$Level managers for objectives, enemy escalation and the final boss loop$q$, $q$Player habit tracker that scores hiding spots, combined with a Q-learning hunter brain$q$, $q$Counter mechanics: flashlight banishes the Clown, eye contact freezes the Doll, and puzzles make the Butcher vulnerable$q$]::text[], ARRAY[$q$Ahsan Tariq, lead Unity developer$q$, $q$Arsal Majid, AI programmer$q$, $q$Tayyab Jahangir, 3D artist and UI/UX designer$q$, $q$Mr. Hashir Hasnain Asghar, project advisor$q$]::text[], $q$Final year project (BSCS) at the School of Systems and Technology, UMT Lahore, completed with 85.7% verified requirements accuracy.$q$, ARRAY[$q$Three linked memory spaces that reveal themselves as one place$q$, $q$Enemies that learn where you hide$q$, $q$A unique counter for each monster$q$, $q$Fresh maze layout every run$q$, $q$Story told through the environment with no dialogue or quest logs$q$]::text[], ARRAY[$q$Q-learning with a habit dictionary that decays so old habits fade over time$q$, $q$Terrain data cloned at runtime so the original asset stays untouched$q$, $q$Camera view checks decide whether the Doll is frozen or stalking$q$, $q$ScriptableObjects keep enemy and generation settings easy to tune$q$]::text[], $q$Windows PC$q$, false, CURRENT_TIMESTAMP)
