VALUES (gen_random_uuid()::text, $q$smart-home-automation$q$, $q$Smart Home Automation$q$, $q$A smart home setup that controls appliances using an ESP32, relays and switches, with the Rainmeter app on a computer acting as the control interface.$q$, $q$IoT$q$, ARRAY[$q$IoT$q$, $q$Embedded$q$, $q$Home Automation$q$, $q$ESP32$q$, $q$Arduino$q$]::text[], $q$ESP32, Arduino, relays, switches, Rainmeter$q$, $q$2024$q$, $q$🏠$q$, $q$#155e75$q$, true, 13, $q$OTHER$q$, $q$ACADEMIC$q$, NULL, $q$Wired relays and switches to the ESP32, programmed the board and set up Rainmeter as the control surface.$q$, ARRAY[$q$ESP32 and relay control circuit$q$, $q$Physical switches alongside app control$q$, $q$Rainmeter interface for controlling devices$q$, $q$Arduino code for the hardware$q$]::text[], ARRAY[$q$Me$q$, $q$Two teammates$q$]::text[], NULL, ARRAY[$q$Control of appliances through relays$q$, $q$Manual switches and computer control$q$, $q$Rainmeter dashboard$q$]::text[], ARRAY[]::text[], NULL, false, CURRENT_TIMESTAMP)
