INSERT INTO "Game" ("id","slug","title","description","tag","categories","tech","year","emoji","bgColor","published","sortOrder","portfolioSection","projectContext","role","contribution","contributions","team","recognition","features","highlights","platforms","inDevelopment","updatedAt")
VALUES (gen_random_uuid()::text, $q$se-attention-yolov8-pothole$q$, $q$Lightweight Object Detection for AR: YOLOv8 with SE Attention$q$, $q$A deep learning research paper on making small object detectors more accurate without making them bigger. It adds a Squeeze-and-Excitation attention block to YOLOv8-Nano and tests it on pothole detection, a low contrast problem that matters for AR navigation on edge devices.$q$, $q$Deep Learning$q$, ARRAY[$q$Deep Learning$q$, $q$Computer Vision$q$, $q$Object Detection$q$, $q$YOLOv8$q$, $q$Attention$q$, $q$Research Paper$q$, $q$AR$q$]::text[], $q$Python, PyTorch, Ultralytics YOLOv8, Roboflow, Google Colab, NVIDIA Tesla T4$q$, $q$2026$q$, $q$🧠$q$, $q$#312e81$q$, true, 14, $q$OTHER$q$, $q$ACADEMIC$q$, $q$Researcher and deep learning developer$q$, $q$I designed the modified YOLOv8-Nano architecture, ran the training and benchmark experiments, and wrote the research paper on the results.$q$, ARRAY[$q$Squeeze-and-Excitation attention block injected after the SPPF layer of the YOLOv8-Nano backbone$q$, $q$Runtime code injection so the custom layer builds inside Ultralytics without editing the library$q$, $q$Fair benchmark of three models (Nano, Small and Nano with SE), all trained from scratch for 60 epochs$q$, $q$Training and evaluation pipeline on the Roboflow pothole dataset at 640 by 640 with mosaic and scaling augmentation$q$, $q$Result charts, validation inference samples and the written paper$q$]::text[], ARRAY[$q$Solo$q$]::text[], NULL, ARRAY[$q$Custom SE attention layer for YOLOv8-Nano$q$, $q$Three model ablation and benchmark study$q$, $q$Pothole detection on road images$q$, $q$Written up as a full research paper$q$]::text[], ARRAY[$q$mAP@0.50 of 0.448 against 0.438 for the plain Nano baseline, a gain of about 2.3 percent$q$, $q$Matches YOLOv8-Small (0.454 mAP) with 71 percent fewer parameters (3.2M against 11.1M)$q$, $q$Shows that channel attention can stand in for extra model depth on edge and AR hardware$q$, $q$All models trained from random weights so the comparison is not skewed by pretraining$q$]::text[], NULL, false, CURRENT_TIMESTAMP)
