INSERT INTO "Game" ("id","slug","title","description","tag","categories","tech","year","emoji","bgColor","published","sortOrder","portfolioSection","projectContext","role","contribution","contributions","team","recognition","features","highlights","platforms","inDevelopment","updatedAt")
VALUES (gen_random_uuid()::text, $q$drought-prediction-lstm$q$, $q$Drought Prediction System: Satellite Data and LSTM$q$, $q$A computer vision and AI project that predicts drought severity across Pakistan from satellite data. It combines MODIS vegetation and CHIRPS rainfall data from 2000 to 2024 with a three layer LSTM that classifies each month from Normal to Extreme. Built for the CS456 computer vision course at UMT Lahore.$q$, $q$Computer Vision$q$, ARRAY[$q$Computer Vision$q$, $q$Remote Sensing$q$, $q$LSTM$q$, $q$Time Series$q$, $q$Google Earth Engine$q$, $q$Climate$q$]::text[], $q$Python, TensorFlow, Google Earth Engine, geemap, pandas, NumPy, scikit-learn, rasterio, MODIS, CHIRPS$q$, $q$2025$q$, $q$🛰️$q$, $q$#854d0e$q$, true, 15, $q$OTHER$q$, $q$ACADEMIC$q$, $q$Computer vision and AI developer$q$, $q$A four person team project under Dr. Jameel Ahmed. We collected the satellite data, built the labelling and training pipeline, and trained and evaluated the drought model, working around deprecated datasets and Colab memory limits.$q$, ARRAY[$q$Data collection from Google Earth Engine: MODIS NDVI (250m) and CHIRPS rainfall (5km) for 2000 to 2024$q$, $q$Monthly aggregation for Pakistan (60.5E to 77.5E, 23.5N to 37.0N) exported as CSV$q$, $q$Z-score standardization and a five class drought label (Normal, Mild, Moderate, Severe, Extreme)$q$, $q$Three layer LSTM trained on 6 month sequences to forecast drought two steps ahead$q$, $q$Training with class weights, early stopping and learning rate reduction to handle imbalanced classes$q$, $q$Evaluation with pixel accuracy, mean IoU, false alarm rate and temporal consistency$q$]::text[], ARRAY[$q$Ahsan Tariq$q$, $q$M. Amish$q$, $q$Hammad Ahmad$q$, $q$Ayesha Gull$q$, $q$Dr. Jameel Ahmed, supervisor$q$]::text[], NULL, ARRAY[$q$Five level drought severity classification$q$, $q$Satellite vegetation and rainfall inputs$q$, $q$Forecast from 6 month sequences$q$, $q$Evaluation with accuracy, IoU, false alarm rate and temporal consistency$q$]::text[], ARRAY[$q$Stacked LSTM (96, 48 and 24 units) with batch normalization, dropout and L2 regularization$q$, $q$Class weights balance the rare severe and extreme drought months$q$, $q$Image resizing to fit Google Colab memory cost an estimated 15 to 20 percent of accuracy$q$, $q$Final evaluation: 0.70 pixel accuracy, 0.10 false alarm rate and 0.05 temporal consistency error$q$]::text[], NULL, false, CURRENT_TIMESTAMP)
